if (Query.Name() != "ContextDependency") return 1;
System.Func<string> read = Query.Name;
if (read() != "ContextDependency") return 2;
if (System.Reflection.Assembly.GetExecutingAssembly().GetName().Name != "ContextApplication") return 3;
System.Console.WriteLine("CLR executing assembly baseline passed");
return 0;
